            try:
                return (int(v[0]), int(v[1]))
            except Exception:
                return default
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_towards(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def get_int(obs, key, default=0):
        try:
            return int(obs.get(key, default))
        except Exception:
            return default

    def extract_positions(value):
        out = []
        if isinstance(value, dict):
            for k in value.values():
                p = pos(k, None)
                if p is not None:
                    out.append(p)
                elif isinstance(k, (list, tuple)):
