        elif isinstance(value, (list, tuple)):
            for item in value:
                p = pos(item, None)
                if p is not None:
                    out.append(p)
                elif isinstance(item, dict):
                    for v in item.values():
                        p = pos(v, None)
                        if p is not None:
                            out.append(p)
        return out

    obs = observation if isinstance(observation, dict) else {}
    env = str(obs.get("environment_name", "")).lower()

    self_pos = pos(obs.get("self_position"), (0, 0))
    opp_pos = pos(obs.get("opponent_position"), self_pos)

    gw = get_int(obs, "grid_width", 0)
    gh = get_int(obs, "grid_height", 0)
    center = (gw // 2, gh // 2) if gw > 0 and gh > 0 else self_pos

    def nearest(targets, origin=self_pos):
        best = None
        best_d = None
        for t in targets:
            p = pos(t, None)
            if p is None:
                continue
            d = manhattan(origin, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def farthest(targets, origin=opp_pos):
        best = None
        best_d = None
        for t in targets:
            p = pos(t, None)
            if p is None:
                continue
            d = manhattan(origin, p)
            if best is None or d > best_d:
                best = p
                best_d = d
        return best

    if "pursuit" in env or "evasion" in env:
        role = str(obs.get("self_role", "pursuer")).lower()
        if "pursuer" in role or obs.get("role") == "pursuer":
