            return step_towards(self_pos, target)
        return step_towards(self_pos, center)

    if "territory" in env or "control" in env:
        targets = []
        for key in ("unclaimed_cells", "neutral_cells", "opponent_territory", "frontier_cells", "targets"):
            targets.extend(extract_positions(obs.get(key)))
        if not targets:
            grid = obs.get("grid")
            targets.extend(extract_positions(grid))
        target = nearest(targets)
        if target is not None:
            return step_towards(self_pos, target)
        return step_towards(self_pos, center)

    resources = []
    for key in ("resources", "resource_positions", "resource_cells", "goals", "targets"):
        resources.extend(extract_positions(obs.get(key)))
    target = nearest(resources)
    if target is not None:
        return step_towards(self_pos, target)

    # fallback: move toward center, but if too close to opponent, back away
